CREATE TABLE financial_goals (id VARCHAR(36) NOT NULL, owner_id VARCHAR(36) NOT NULL, name VARCHAR(150) NOT NULL, description VARCHAR(2000), target_amount DECIMAL(19,2) NOT NULL, target_date DATE, status VARCHAR(20) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, version BIGINT NULL, PRIMARY KEY(id), CONSTRAINT ck_goals_target CHECK(target_amount > 0));
CREATE TABLE goal_contributions (id VARCHAR(36) NOT NULL, owner_id VARCHAR(36) NOT NULL, goal_id VARCHAR(36) NOT NULL, amount DECIMAL(19,2) NOT NULL, occurred_at TIMESTAMP(6) NOT NULL, note VARCHAR(1000), created_at TIMESTAMP(6) NOT NULL, version BIGINT NULL, PRIMARY KEY(id), CONSTRAINT ck_goal_contribution_amount CHECK(amount > 0), CONSTRAINT fk_goal_contribution_goal FOREIGN KEY(goal_id) REFERENCES financial_goals(id));
CREATE INDEX idx_goals_owner_status ON financial_goals(owner_id,status); CREATE INDEX idx_contributions_owner_goal ON goal_contributions(owner_id,goal_id,occurred_at);
